-- Реальные позиции электрики из трёх последних счетов Eleganz (14.07, 18.08,
-- 31.08.2026), которые владелец прислал. Это фактически уплаченные рубли —
-- точнее, чем пересчёт долларового прайса по курсу.
--
-- Цена берётся из САМОГО СВЕЖЕГО счёта, где позиция встречается: они растут
-- (профиль 68→73→75, лента 96N 79→85→88, БП 100 Вт 395→424→439).

update public.mirror_lighting_components set active = false where name like '%— заполнить';


-- Прежние позиции без артикула (цены из долларового прайса) выключены: их
-- заменили строки из счетов, иначе в справочнике два ответа на один вопрос.
update public.mirror_lighting_components set active = false where id in (31,32,33,34,35,39,40,41,42,43,44);
